-- 品质不良柏拉图 · 产品分类扩充（消费电子 / 智能电源 / 储能电源 / 车载）
-- 幂等：老行回填 UPDATE（WHERE product_category IS NULL）+ INSERT OR IGNORE（显式 id 4001+）
-- 数据红线：不出现 line_code='SMT-1' AND product_model='A型号'；缺陷类型严格复用既有 10 个词表
-- 工段->线体：SMT(SMT-3) / PCM(PCM-1) / PACK(PACK-1) / 整机(ASSY-1)
-- 网格：产品分类(4) x 工段(4) x 日期(2026-08-01~10-15, 76 天) x 类别(2) = 2432 行
-- 由一次性脚本生成（随机种子固定 20261020，可复现）
-- ============================================================

-- 老演示库回填：按型号判定产品分类（无型号/无工段的历史行保持 NULL）
UPDATE quality_defect SET product_category = CASE
  WHEN product_model IN ('PCM-13S', 'PCM-16S') THEN '消费电子'
  WHEN product_model IN ('BT-48V20', 'BT-60V30') THEN '智能电源'
  WHEN product_model IN ('ESS-5K', 'ESS-10K') THEN '储能电源'
  WHEN product_model IN ('PACK-4820', 'PACK-6030') THEN '车载'
  WHEN product_model IN ('CE-18650', 'CE-PCM13', 'CE-PACK-65W', 'CE-PB20K') THEN '消费电子'
  WHEN product_model IN ('SM-BMS48', 'SM-PACK-48', 'SM-PSU-3K2') THEN '智能电源'
  WHEN product_model IN ('ES-BMS100', 'ES-PCM5K', 'ES-PACK5K') THEN '储能电源'
  WHEN product_model IN ('EV-18650', 'EV-BMS01', 'EV-PACK60', 'EV-OBC6K6') THEN '车载'
  ELSE product_category END
WHERE product_category IS NULL AND process_stage IS NOT NULL;

